<header class="admin-page-head compact-head"><div><a class="admin-back-link" href="<?= e(admin_url('/messages')) ?>">← Back to enquiries</a><p class="admin-eyebrow">Inbox / <?= e($message['message_type']) ?></p><h1><?= e($message['name']) ?></h1><p class="admin-lede"><?= e($message['business_name'] ?: $message['email']) ?> · <?= e(date('d M Y, H:i', strtotime($message['created_at']))) ?></p></div><form method="post" action="<?= e(admin_url('/messages')) ?>" data-confirm="Delete this enquiry?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="admin_action" value="delete_message"><input type="hidden" name="id" value="<?= e($message['id']) ?>"><button class="admin-danger-button" type="submit">Delete enquiry</button></form></header>
